:root {
  /* Color palette */
  --bg-main: #FFF8F0;          /* warm off‑white */
  --brown-dark: #8C5A3C;       /* deep brown */
  --brown-light: #C08552;      /* lighter brown/orange */
  --accent: #8C5A3C;           /* using dark brown as accent */
  --glass-bg: rgba(255,255,255,0.15);
  --text-dark: #222222;
}

/* Global Reset */
* { margin:0; padding:0; box-sizing:border-box; }
body { font-family: 'Inter', sans-serif; background: var(--bg-main); color: var(--text-dark); line-height:1.6; overflow-x:hidden; }
a { color:inherit; text-decoration:none; }

/* Header */
.site-header { 
  position: sticky; 
  top: 0; 
  background: var(--glass-bg); 
  backdrop-filter: blur(10px); 
  z-index: 1000; 
  display: flex; 
  justify-content: center; 
  padding: 1rem; 
  border-bottom: 2px solid rgba(140, 90, 60, 0.2);
}
.logo-wrapper { text-align:center; }
.logo { max-height: 100px; }

/* Main Content */
.main-content {
  max-width: 1200px;
  margin: 3rem auto;
  padding: 0 2rem;
  display: flex;
  flex-direction: column;
  gap: 4rem;
}

/* App Sections */
.app-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
  background: var(--glass-bg);
  padding: 3rem;
  border-radius: 20px;
  box-shadow: 0 10px 40px rgba(140, 90, 60, 0.1);
  border: 1px solid rgba(140, 90, 60, 0.2);
  transition: transform 0.3s ease;
}

.app-section:hover {
  transform: translateY(-5px);
}

.app-info {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2rem;
}

.app-logo {
  max-width: 300px;
  width: 100%;
  height: auto;
  border-radius: 24px;
  box-shadow: 0 10px 25px rgba(0,0,0,0.15);
  transition: transform 0.3s;
}

.app-logo:hover {
  transform: scale(1.03);
}

.play-button {
  display: inline-block;
  transition: transform 0.3s;
}

.play-button img {
  height: 65px;
}

.play-button:hover {
  transform: scale(1.05);
}

/* Sliders */
.app-screenshots {
  display: flex;
  justify-content: center;
  align-items: center;
}

.slider {
  position: relative;
  width: 250px;
  height: 520px;
  border-radius: 35px;
  overflow: hidden;
  box-shadow: 0 20px 40px rgba(0,0,0,0.25);
  border: 8px solid var(--brown-dark);
  background: #000;
}

.slide {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transition: opacity 1s ease-in-out, transform 5s linear;
}

.slide.active {
  opacity: 1;
  transform: scale(1.05); /* Slight zoom animation during the 5s wait */
}

/* Footer */
.site-footer { 
  text-align: center; 
  padding: 2rem; 
  margin-top: 3rem; 
  font-family: 'Outfit', sans-serif; 
  color: var(--brown-dark); 
  font-weight: 600;
  border-top: 1px solid rgba(140, 90, 60, 0.2); 
}

/* Reveal animation */
.reveal { opacity:0; transform:translateY(30px); transition:opacity 0.8s ease-out, transform 0.8s ease-out; }
.reveal.active { opacity:1; transform:translateY(0); }

/* Responsive layout */
@media (max-width: 900px) {
  .app-section {
    grid-template-columns: 1fr;
    gap: 3rem;
    padding: 2rem;
  }

  /* Ensure consistent order on mobile: Logo + button on top, slider below */
  .app-section .app-info {
    order: 1;
  }
  .app-section .app-screenshots {
    order: 2;
  }

  .slider {
    width: 220px;
    height: 460px;
  }
}

// Reveal animation using IntersectionObserver
const revealElements = document.querySelectorAll('.reveal');
const observerOptions = {
  threshold: 0.15,
};
const revealObserver = new IntersectionObserver((entries, observer) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('active');
      observer.unobserve(entry.target);
    }
  });
}, observerOptions);
revealElements.forEach(el => revealObserver.observe(el));

// Sliders logic
function initSlider(sliderId) {
  const slider = document.getElementById(sliderId);
  if (!slider) return;
  const slides = slider.querySelectorAll('.slide');
  if (slides.length === 0) return;

  let currentIndex = 0;

  setInterval(() => {
    slides[currentIndex].classList.remove('active');
    currentIndex = (currentIndex + 1) % slides.length;
    slides[currentIndex].classList.add('active');
  }, 5000); // Change every 5 seconds
}

// Initialize sliders for both apps
document.addEventListener('DOMContentLoaded', () => {
  initSlider('allah-slider');
  initSlider('pasea-slider');
});

